def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = [
        (lambda r, c: r),
        (lambda r, c: c - r),
        (lambda r, c: r + c),
    ]
    best = None
    for key_fn in candidates:
        groups = {}
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    groups.setdefault(key_fn(r, c), set()).add(value)
        uniform = {k: next(iter(values)) for k, values in groups.items() if len(values) == 1}
        coverage = sum(sum(1 for r, row in enumerate(grid) for c, value in enumerate(row)
                           if value and key_fn(r, c) == k) for k in uniform)
        score = (coverage, len(uniform))
        if best is None or score > best[0]:
            best = (score, key_fn, uniform)
    _, key_fn, clues = best
    period = len(clues)
    pattern = {k % period: value for k, value in clues.items()}
    return [[pattern[key_fn(r, c) % period] for c in range(w)] for r in range(h)]
